EventHandler? saved = null;
saved += (s, e) => Console.WriteLine("to log");
saved += (s, e) => throw new IOException("disk full");
saved += (s, e) => Console.WriteLine("to cache");   // not called by saved(...)

foreach (EventHandler h in saved.GetInvocationList())
{
    try { h(null, EventArgs.Empty); }
    catch (Exception ex) { Console.WriteLine(ex.Message); }
}

